const hieleras = ['H-01','H-02','H-03','H-04','H-05'];
const sensores = ['A','B'];
let estado = context.get('estado') || {};
const enFalla = hieleras.filter((h) => estado[h + ':estado'] && estado[h + ':estado'].startsWith('falla')).length;
const msgs = [];
for (const h of hieleras) {
  if (estado[h] === undefined) {
    estado[h] = 3.5 + Math.random() * 3.5;
    estado[h + ':estado'] = 'normal';
  }
  let t = estado[h];
  const s = estado[h + ':estado'];
  if (s === 'falla-sube') {
    t += 0.4 + Math.random() * 0.5;
    if (t >= 9.3) estado[h + ':estado'] = 'recupera';
  } else if (s === 'falla-baja') {
    t -= 0.35 + Math.random() * 0.45;
    if (t <= 1.4) estado[h + ':estado'] = 'recupera';
  } else if (s === 'recupera') {
    const paso = 0.5 + Math.random() * 0.4;
    t += (5 - t > 0 ? 1 : -1) * paso;
    if (t >= 2.5 && t <= 7.5) estado[h + ':estado'] = 'normal';
  } else {
    t += (Math.random() - 0.5) * 0.5;
    if (enFalla < 2 && Math.random() < 0.05) {
      estado[h + ':estado'] = Math.random() < 0.5 ? 'falla-sube' : 'falla-baja';
    }
  }
  t = Math.min(9.3, Math.max(1.4, t));
  estado[h] = t;
  for (const sn of sensores) {
    const lectura = sn === 'A' ? t : t + (Math.random() - 0.5) * 0.3;
    msgs.push({ payload: { sensorId: 'S-' + h.slice(2) + '-' + sn, hielera: h, temperatura: Math.round(lectura * 100) / 100 } });
  }
}
context.set('estado', estado);
return [msgs];

const hieleras = ['H-01','H-02','H-03','H-04','H-05'];
const sensores = ['A','B'];
const cuantas = 2 + Math.floor(Math.random() * 2);
const elegidas = hieleras.slice().sort(() => Math.random() - 0.5).slice(0, cuantas);
const msgs = [];
for (const h of elegidas) {
  const sn = sensores[Math.floor(Math.random() * 2)];
  const sube = Math.random() < 0.5;
  const temp = sube ? 8.3 + Math.random() * 0.9 : 1.3 + Math.random() * 0.6;
  msgs.push({ payload: { sensorId: 'S-' + h.slice(2) + '-' + sn, hielera: h, temperatura: Math.round(temp * 100) / 100 } });
}
return [msgs];

